  corrections jsonb := '[{"legacy_id":600641,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nLundi | 6 | 3\n\nCombien de livres sont indiqués pour lundi ?","choices":["6","3","9","4"],"correct_position":1,"explanation":"À l’intersection de la ligne « lundi » et de la colonne « Livres », on lit 6.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600642,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nMardi | 8 | 4\n\nCombien de jeux sont indiqués pour mardi ?","choices":["8","4","12","2"],"correct_position":2,"explanation":"À l’intersection de la ligne « mardi » et de la colonne « Jeux », on lit 4.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600643,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nMercredi | 10 | 5\n\nCombien de livres sont indiqués pour mercredi ?","choices":["5","15","10","8"],"correct_position":3,"explanation":"À l’intersection de la ligne « mercredi » et de la colonne « Livres », on lit 10.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600644,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nJeudi | 12 | 6\n\nCombien de jeux sont indiqués pour jeudi ?","choices":["12","18","4","6"],"correct_position":4,"explanation":"À l’intersection de la ligne « jeudi » et de la colonne « Jeux », on lit 6.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600645,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nVendredi | 14 | 7\n\nCombien de livres sont indiqués pour vendredi ?","choices":["14","7","21","12"],"correct_position":1,"explanation":"À l’intersection de la ligne « vendredi » et de la colonne « Livres », on lit 14.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600646,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nSamedi | 16 | 8\n\nCombien de jeux sont indiqués pour samedi ?","choices":["16","8","24","6"],"correct_position":2,"explanation":"À l’intersection de la ligne « samedi » et de la colonne « Jeux », on lit 8.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600647,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nDimanche | 18 | 9\n\nCombien de livres sont indiqués pour dimanche ?","choices":["9","27","18","16"],"correct_position":3,"explanation":"À l’intersection de la ligne « dimanche » et de la colonne « Livres », on lit 18.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600648,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nLundi suivant | 20 | 10\n\nCombien de jeux sont indiqués pour lundi suivant ?","choices":["20","30","8","10"],"correct_position":4,"explanation":"À l’intersection de la ligne « lundi suivant » et de la colonne « Jeux », on lit 10.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600649,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nMardi suivant | 22 | 11\n\nCombien de livres sont indiqués pour mardi suivant ?","choices":["22","11","33","20"],"correct_position":1,"explanation":"À l’intersection de la ligne « mardi suivant » et de la colonne « Livres », on lit 22.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":600650,"prompt":"Observe le tableau :\n\nJour | Livres | Jeux\nMercredi suivant | 24 | 12\n\nCombien de jeux sont indiqués pour mercredi suivant ?","choices":["24","12","36","10"],"correct_position":2,"explanation":"À l’intersection de la ligne « mercredi suivant » et de la colonne « Jeux », on lit 12.","change_comment":"La donnée demandée alterne désormais entre la colonne Livres et la colonne Jeux."},{"legacy_id":